import 'package:flutter/material.dart';
import 'models/store_product.dart';
import 'services/woocommerce_store_service.dart';
const akeTeal=Color(0xFF01ADA5), akeGrey=Color(0xFF57595B), akeInk=Color(0xFF202426), akeBackground=Color(0xFFF3F6F6);
void main()=>runApp(const AkeApp());
class AkeApp extends StatelessWidget { const AkeApp({super.key}); @override Widget build(BuildContext context)=>MaterialApp(debugShowCheckedModeBanner:false,title:'AKE Forging',theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:akeTeal),scaffoldBackgroundColor:akeBackground),home:const AkeShell());}
class AkeShell extends StatefulWidget {const AkeShell({super.key}); @override State<AkeShell> createState()=>_AkeShellState();}
class _AkeShellState extends State<AkeShell>{int selectedIndex=0;final pages=const[HomePage(),CategoriesPage(),OrdersPage(),AccountPage()];@override Widget build(BuildContext context)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(body:SafeArea(child:IndexedStack(index:selectedIndex,children:pages)),bottomNavigationBar:NavigationBar(selectedIndex:selectedIndex,onDestinationSelected:(v)=>setState(()=>selectedIndex=v),backgroundColor:Colors.white,indicatorColor:akeTeal.withValues(alpha:.13),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home),label:'خانه'),NavigationDestination(icon:Icon(Icons.category_outlined),selectedIcon:Icon(Icons.category),label:'دسته‌بندی'),NavigationDestination(icon:Icon(Icons.receipt_long_outlined),selectedIcon:Icon(Icons.receipt_long),label:'سفارش‌ها'),NavigationDestination(icon:Icon(Icons.person_outline),selectedIcon:Icon(Icons.person),label:'حساب من')])));}
class HomePage extends StatefulWidget{const HomePage({super.key});@override State<HomePage> createState()=>_HomePageState();}
class _HomePageState extends State<HomePage>{final service=WooCommerceStoreService(),controller=TextEditingController();List<StoreProduct> products=[];List<StoreCategory> categories=[];bool loading=true;String? error;String query='',selectedCategory='';
@override void initState(){super.initState();_load();}
@override void dispose(){controller.dispose();service.dispose();super.dispose();}
Future<void> _load()async{setState(()=>{loading=true,error=null});try{final r=await Future.wait([service.fetchProducts(),service.fetchCategories()]);if(!mounted)return;setState(()=>{products=r[0] as List<StoreProduct>,categories=r[1] as List<StoreCategory>,loading=false});}catch(e){if(!mounted)return;setState(()=>{error=e.toString(),loading=false});}}
List<StoreProduct> get filtered{final q=query.trim().toLowerCase();return products.where((p)=>(q.isEmpty||p.name.toLowerCase().contains(q)||p.sku.toLowerCase().contains(q)||p.categories.any((c)=>c.toLowerCase().contains(q)))&&(selectedCategory.isEmpty||p.categories.contains(selectedCategory))).toList();}
@override Widget build(BuildContext context)=>RefreshIndicator(color:akeTeal,onRefresh:_load,child:CustomScrollView(physics:const AlwaysScrollableScrollPhysics(),slivers:[
SliverToBoxAdapter(child:Padding(padding:const EdgeInsets.fromLTRB(20,16,20,8),child:Row(children:[Container(width:48,height:48,decoration:BoxDecoration(color:akeTeal,borderRadius:BorderRadius.circular(14)),child:const Icon(Icons.precision_manufacturing,color:Colors.white,size:28)),const SizedBox(width:12),const Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('آریان کوب اسپادانا',style:TextStyle(fontSize:18,fontWeight:FontWeight.w900,color:akeInk)),SizedBox(height:3),Text('AKE FORGING',style:TextStyle(fontSize:11,letterSpacing:1.5,color:akeGrey,fontWeight:FontWeight.bold))])),IconButton(onPressed:_load,icon:const Icon(Icons.refresh_rounded))]))),
SliverToBoxAdapter(child:Padding(padding:const EdgeInsets.fromLTRB(20,12,20,18),child:TextField(controller:controller,onChanged:(v)=>setState(()=>query=v),decoration:InputDecoration(hintText:'جست‌وجوی محصول یا کد فنی...',prefixIcon:const Icon(Icons.search,color:akeTeal),filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.circular(16),borderSide:BorderSide.none),contentPadding:const EdgeInsets.symmetric(vertical:16))))),
SliverToBoxAdapter(child:Padding(padding:const EdgeInsets.symmetric(horizontal:20),child:Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(borderRadius:BorderRadius.circular(22),gradient:const LinearGradient(colors:[akeTeal,Color(0xFF087E79)],begin:Alignment.topRight,end:Alignment.bottomLeft)),child:const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('مهندسی قدرت،\nکیفیت در هر ضربه',style:TextStyle(color:Colors.white,fontSize:23,height:1.5,fontWeight:FontWeight.w900)),SizedBox(height:10),Text('تولید قطعات فورج با تکیه بر دانش فنی و فناوری روز',style:TextStyle(color:Colors.white,height:1.7)),SizedBox(height:18),Row(children:[Icon(Icons.verified_outlined,color:Colors.white),SizedBox(width:7),Text('کیفیت و دقت در فرآیند تولید',style:TextStyle(color:Colors.white,fontWeight:FontWeight.bold))])]))),
SliverToBoxAdapter(child:Padding(padding:const EdgeInsets.fromLTRB(20,26,20,12),child:Row(children:[const Expanded(child:Text('دسته‌بندی محصولات',style:TextStyle(color:akeInk,fontSize:17,fontWeight:FontWeight.w900))),if(selectedCategory.isNotEmpty)TextButton(onPressed:()=>setState(()=>selectedCategory=''),child:const Text('پاک کردن فیلتر'))]))),
if(categories.isNotEmpty)SliverToBoxAdapter(child:SizedBox(height:106,child:ListView(scrollDirection:Axis.horizontal,padding:const EdgeInsets.symmetric(horizontal:20),children:[for(final c in categories)GestureDetector(onTap:()=>setState(()=>selectedCategory=selectedCategory==c.name?'':c.name),child:Container(width:100,margin:const EdgeInsets.only(left:10),padding:const EdgeInsets.all(10),decoration:BoxDecoration(color:selectedCategory==c.name?akeTeal.withValues(alpha:.14):Colors.white,borderRadius:BorderRadius.circular(16),border:Border.all(color:selectedCategory==c.name?akeTeal:Colors.transparent)),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(Icons.category_outlined,color:akeTeal,size:27),const SizedBox(height:9),Text(c.name,maxLines:2,textAlign:TextAlign.center,style:const TextStyle(fontSize:11,fontWeight:FontWeight.w700))])))]))),
SliverToBoxAdapter(child:Padding(padding:const EdgeInsets.fromLTRB(20,26,20,12),child:Text(query.isEmpty&&selectedCategory.isEmpty?'محصولات فروشگاه':'نتایج جست‌وجو',style:const TextStyle(color:akeInk,fontSize:17,fontWeight:FontWeight.w900)))),
if(loading)const SliverToBoxAdapter(child:Padding(padding:EdgeInsets.all(36),child:Center(child:CircularProgressIndicator(color:akeTeal))))
else if(error!=null)SliverToBoxAdapter(child:Padding(padding:const EdgeInsets.all(24),child:Center(child:Column(children:[const Icon(Icons.cloud_off_outlined,color:akeGrey,size:44),const SizedBox(height:12),Text(error!,textAlign:TextAlign.center),const SizedBox(height:14),FilledButton(onPressed:_load,style:FilledButton.styleFrom(backgroundColor:akeTeal),child:const Text('تلاش مجدد'))]))))
else if(filtered.isEmpty)const SliverToBoxAdapter(child:Padding(padding:EdgeInsets.all(28),child:Center(child:Text('محصولی با این مشخصات پیدا نشد.'))))
else SliverPadding(padding:const EdgeInsets.fromLTRB(20,0,20,28),sliver:SliverGrid(delegate:SliverChildBuilderDelegate((context,index)=>StoreProductCard(product:filtered[index]),childCount:filtered.length),gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:2,mainAxisSpacing:12,crossAxisSpacing:12,childAspectRatio:.68)))
]));}
class StoreProductCard extends StatelessWidget{final StoreProduct product;const StoreProductCard({super.key,required this.product});@override Widget build(BuildContext context)=>Container(padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(17)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Expanded(child:Container(width:double.infinity,clipBehavior:Clip.antiAlias,decoration:BoxDecoration(color:akeTeal.withValues(alpha:.07),borderRadius:BorderRadius.circular(13)),child:product.imageUrl.isNotEmpty?Image.network(product.imageUrl,fit:BoxFit.contain,errorBuilder:(_,__,___)=>const Icon(Icons.precision_manufacturing,color:akeTeal,size:48),loadingBuilder:(context,child,progress)=>progress==null?child:const Center(child:CircularProgressIndicator(strokeWidth:2,color:akeTeal))):const Icon(Icons.precision_manufacturing,color:akeTeal,size:48))),const SizedBox(height:9),Text(product.name,maxLines:2,overflow:TextOverflow.ellipsis,style:const TextStyle(fontWeight:FontWeight.w900,fontSize:12,height:1.5)),const SizedBox(height:4),Text(product.sku.isNotEmpty?'کد: ${product.sku}':'شناسه: ${product.id}',maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(color:akeGrey,fontSize:10)),const SizedBox(height:6),Text(product.displayPrice.isNotEmpty?product.displayPrice:'استعلام قیمت',maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(color:akeTeal,fontWeight:FontWeight.w900,fontSize:12)),const SizedBox(height:7),SizedBox(width:double.infinity,child:FilledButton(style:FilledButton.styleFrom(backgroundColor:akeTeal,padding:const EdgeInsets.symmetric(vertical:8)),onPressed:()=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('برای ${product.name}، فرآیند خرید در مرحله بعد اضافه می‌شود.'))),child:Text(product.inStock?'مشاهده محصول':'ناموجود',style:const TextStyle(fontSize:11))))]));}
class CategoriesPage extends StatefulWidget{const CategoriesPage({super.key});@override State<CategoriesPage> createState()=>_CategoriesPageState();}
class _CategoriesPageState extends State<CategoriesPage>{final service=WooCommerceStoreService();List<StoreCategory> categories=[];bool loading=true;String? error;@override void initState(){super.initState();_load();}@override void dispose(){service.dispose();super.dispose();}Future<void> _load()async{setState(()=>{loading=true,error=null});try{final r=await service.fetchCategories();if(!mounted)return;setState(()=>{categories=r,loading=false});}catch(e){if(!mounted)return;setState(()=>{error=e.toString(),loading=false});}}
@override Widget build(BuildContext context)=>PageScaffold(title:'دسته‌بندی محصولات',child:loading?const Center(child:CircularProgressIndicator(color:akeTeal)):error!=null?Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Text(error!,textAlign:TextAlign.center),FilledButton(onPressed:_load,child:const Text('تلاش مجدد'))])):RefreshIndicator(color:akeTeal,onRefresh:_load,child:ListView(padding:const EdgeInsets.all(20),children:[for(final c in categories)Card(color:Colors.white,child:ListTile(leading:CircleAvatar(backgroundColor:akeTeal.withValues(alpha:.12),child:c.imageUrl.isNotEmpty?ClipOval(child:Image.network(c.imageUrl,fit:BoxFit.cover,errorBuilder:(_,__,___)=>const Icon(Icons.category,color:akeTeal))):const Icon(Icons.category,color:akeTeal)),title:Text(c.name),subtitle:Text('شناسه: ${c.id}'),trailing:const Icon(Icons.chevron_left)))])));}
class OrdersPage extends StatelessWidget{const OrdersPage({super.key});@override Widget build(BuildContext context)=>const PageScaffold(title:'سفارش‌های من',child:EmptyState(icon:Icons.receipt_long_outlined,title:'هنوز سفارشی ثبت نشده است',subtitle:'اتصال حساب کاربری و نمایش سفارش‌ها در مرحله بعد اضافه می‌شود.'));}
class AccountPage extends StatelessWidget{const AccountPage({super.key});@override Widget build(BuildContext context)=>const PageScaffold(title:'حساب کاربری',child:ListView(padding:EdgeInsets.all(20),children:[ListTile(leading:Icon(Icons.person_outline,color:akeTeal),title:Text('اطلاعات حساب کاربری'),trailing:Icon(Icons.chevron_left)),Divider(),ListTile(leading:Icon(Icons.location_on_outlined,color:akeTeal),title:Text('نشانی‌های من'),trailing:Icon(Icons.chevron_left)),Divider(),ListTile(leading:Icon(Icons.support_agent,color:akeTeal),title:Text('پشتیبانی و تماس با ما'),trailing:Icon(Icons.chevron_left))]));}
class PageScaffold extends StatelessWidget{final String title;final Widget child;const PageScaffold({super.key,required this.title,required this.child});@override Widget build(BuildContext context)=>Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Padding(padding:const EdgeInsets.fromLTRB(20,20,20,12),child:Text(title,style:const TextStyle(color:akeInk,fontSize:21,fontWeight:FontWeight.w900))),Expanded(child:child)]);}
class EmptyState extends StatelessWidget{final IconData icon;final String title,subtitle;const EmptyState({super.key,required this.icon,required this.title,required this.subtitle});@override Widget build(BuildContext context)=>Center(child:Padding(padding:const EdgeInsets.all(30),child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(icon,size:58,color:akeTeal),const SizedBox(height:16),Text(title,textAlign:TextAlign.center,style:const TextStyle(fontWeight:FontWeight.w900,fontSize:16)),const SizedBox(height:8),Text(subtitle,textAlign:TextAlign.center,style:const TextStyle(color:akeGrey,height:1.7))])));}
